'use strict';

// MODULES //

var isRowMajor = require( '@stdlib/ndarray/base/assert/is-row-major' );
var PINF = require( '@stdlib/constants/float64/pinf' );


// MAIN //

/**
* Returns the maximum absolute value of a strided matrix, or `NaN` if the matrix contains a non-finite value.
*
* @private
* @param {NonNegativeInteger} M - number of rows
* @param {NonNegativeInteger} N - number of columns
* @param {Float64Array} X - input matrix
* @param {integer} strideX1 - stride of the first dimension of `X`
* @param {integer} strideX2 - stride of the second dimension of `X`
* @param {NonNegativeInteger} offsetX - starting index for `X`
* @returns {number} maximum absolute value or `NaN`
*
* @example
* var Float64Array = require( '@stdlib/array/float64' );
*
* var X = new Float64Array( [ 1.0, -5.0, 3.0, 4.0 ] );
*
* var v = maxAbs( 2, 2, X, 2, 1, 0 );
* // returns 5.0
*
* @example
* var Float64Array = require( '@stdlib/array/float64' );
*
* var X = new Float64Array( [ 1.0, -Infinity, 3.0, 4.0 ] );
*
* var v = maxAbs( 2, 2, X, 2, 1, 0 );
* // returns NaN
*/
function maxAbs( M, N, X, strideX1, strideX2, offsetX ) {
	var dx0;
	var dx1;
	var S0;
	var S1;
	var i0;
	var i1;
	var ix;
	var v;
	var m;

	if ( isRowMajor( [ strideX1, strideX2 ] ) ) {
		S0 = N;
		S1 = M;
		dx0 = strideX2;
		dx1 = strideX1 - ( S0*strideX2 );
	} else { // column-major
		S0 = M;
		S1 = N;
		dx0 = strideX1;
		dx1 = strideX2 - ( S0*strideX1 );
	}
	m = 0.0;
	ix = offsetX;
	for ( i1 = 0; i1 < S1; i1++ ) {
		for ( i0 = 0; i0 < S0; i0++ ) {
			v = X[ ix ];
			if ( v < 0.0 ) {
				v = -v;
			}
			if ( v > m ) {
				m = v;
			} else if ( v !== v ) {
				return NaN;
			}
			ix += dx0;
		}
		ix += dx1;
	}
	if ( m === PINF ) {
		return NaN;
	}
	return m;
}


// EXPORTS //

module.exports = maxAbs;
